  '登陆艇': '登陸艇',  // UNITS.lnd.name

  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': '造價低廉，可佔領建築，可進入山地與河流。',  // UNITS.inf.desc
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': '裝備火箭筒的步兵，可佔領建築，對戰車傷害較高，在山地、河流上的移動消耗為 1。',  // UNITS.mech.desc
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': '射程 2–4 的遠程步兵，擅長攻擊步兵類單位，也可攻擊輕型車輛和直升機。在山地上射程 +1。移動後不可攻擊。',  // UNITS.snp.desc
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': '射程 1–2，移動後仍可攻擊。攻擊時目標的地形防禦減半，擅長攻擊位於建築、森林、山地的步兵類單位。攻擊 2 格外的目標時不受反擊。在山地上射程 +1。不可攻擊航空單位和艦艇，不可佔領。',  // UNITS.grn.desc
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': '射程 1，攻擊時無視目標的地形防禦，擅長攻擊位於建築、山地的步兵類單位。迷霧開啟時，可發現周圍 8 格森林、廢墟中的隱蔽單位。不敵遠程單位和車輛，不可攻擊航空單位和艦艇，不可佔領。',  // UNITS.flm.desc
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': '無武裝。相鄰的我方步兵類單位每回合恢復 2 HP（無需支付資金）。多名醫護兵的效果不疊加。',  // UNITS.mdc.desc
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': '騎乘機車的步兵，可佔領建築，移動力高，適合佔領遠處的建築。不可進入山地。',  // UNITS.bik.desc
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': '陸上單位中移動力最高，擅長攻擊步兵類單位和無掩護的火砲，不敵戰車。',  // UNITS.rec.desc
  '陆上主力，造价较低，攻击与防御均衡。': '陸上主力，造價較低，攻擊與防禦均衡。',  // UNITS.tnk.desc
  '攻击与防御高于轻型坦克，造价适中。': '攻擊與防禦高於輕型戰車，造價適中。',  // UNITS.med.desc
  '陆上单位中攻击与防御最高，造价高，移动力低。': '陸上單位中攻擊與防禦最高，造價高，移動力低。',  // UNITS.hvy.desc
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': '射程 2–3，可攻擊艦艇。移動後不可攻擊，不可攻擊相鄰的敵方單位。',  // UNITS.art.desc
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': '射程 3–5，射程長於自走砲，擅長攻擊重型車輛。移動後不可攻擊。',  // UNITS.rkt.desc
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': '射程 1，擅長攻擊航空單位，對步兵類單位傷害也較高。',  // UNITS.aa.desc
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': '無武裝。相鄰的我方車輛、航空單位、艦艇每回合恢復 1 HP（無需支付資金）。',  // UNITS.rep.desc
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': '移動不受地形影響，擅長攻擊陸上單位，不敵防空車。',  // UNITS.cop.desc
