  // ── 兵种说明 ──

  // ── 地图简介 ──
  '16×12 · 河边小镇，新手图': '16×12 · 河邊小鎮，新手地圖',  // MAPS.0.size
  '小河斜穿麦田，镇子跨河而建。两座桥通坦克，步兵可以从西南的浅滩蹚过去，东北的矿山是第三条路。先抢桥头的兵工厂和医院，再过河。': '小河斜穿麥田，鎮子跨河而建。兩座橋可通行戰車，步兵可以從西南的淺灘涉水過去，東北的礦山是第三條路。先搶下橋頭的兵工廠和醫院，再過河。',  // MAPS.0.blurb
  '18×12 · 海边岬角，初识海战': '18×12 · 海邊岬角，初識海戰',  // MAPS.1.size
  '沿海公路最近，但整条路都在舰炮射程里；内陆要翻碉堡把守的隘口。岬角根上是渔村的兵工厂和渔港，顶端是灯塔，登陆艇可以把步兵直接送上岬角的沙滩。': '沿海公路最近，但整條路都在艦砲射程內；走內陸要翻越碉堡把守的隘口。岬角根部是漁村的兵工廠和漁港，頂端是燈塔，登陸艇可以把步兵直接送上岬角的沙灘。',  // MAPS.1.blurb
  '28×18 · 港口都市，江心岛兵工厂，海军炮击桥头': '28×18 · 港口都市，江心島兵工廠，海軍砲擊橋頭',  // MAPS.2.size
  '30×18 · 一道山脉三处隘口，关城攻防': '30×18 · 一道山脈三處隘口，關城攻防',  // MAPS.3.size
  '30×20 · 群岛两栖战，岛链公路绕远，登陆艇抄近路': '30×20 · 群島兩棲戰，島鏈公路繞遠，登陸艇抄近路',  // MAPS.4.size
  '26×18 · 两条堤坝路四座桥，步兵蹚河钻沼泽': '26×18 · 兩條堤壩路四座橋，步兵涉水鑽沼澤',  // MAPS.5.size
  '大河入海前分成两条汊流，夹着一座沼泽岛，渔村、医院、旧堤防碉堡和海边的炼油厂都在岛上。车辆只能走上堤、海堤两条公路过桥；步兵可以蹚河钻芦苇荡，直升机哪里都能去，炮艇能贴着河口和潮沟打海堤上的部队。': '大河入海前分成兩條汊流，夾著一座沼澤島，漁村、醫院、舊堤防碉堡和海邊的煉油廠都在島上。車輛只能走上堤、海堤兩條公路過橋；步兵可以涉水鑽蘆葦叢，直升機哪裡都能去，砲艇能貼著河口和潮溝打海堤上的部隊。',  // MAPS.5.blurb
  '32×20 · 两湖夹一城，海陆空总决战': '32×20 · 兩湖夾一城，海陸空總決戰',  // MAPS.15.size
  '32×32 · 3 个阵营 · 三河汇流，河心古城': '32×32 · 3 個陣營 · 三河匯流，河心古城',  // MAPS.17.size
  '40×32 · 4 个阵营 · 陆上同盟对海上同盟，界河五桥': '40×32 · 4 個陣營 · 陸上同盟對海上同盟，界河五橋',  // MAPS.18.size
  '36×36 · 4 个阵营 · 一对三围城': '36×36 · 4 個陣營 · 一對三圍城',  // MAPS.19.size
  '40×40 · 4 个阵营 · 群岛海空战，十二座港口': '40×40 · 4 個陣營 · 群島海空戰，十二座港口',  // MAPS.20.size
  '40×40 · 4 个阵营 · 城市巷战，十二座中立兵工厂': '40×40 · 4 個陣營 · 城市巷戰，十二座中立兵工廠',  // MAPS.21.size
  '赤焰首都炉城被四支军队各占一角。老城墙里有中立机场、雷达塔和医院，城外是炼钢区、码头、商业区和编组站，每个城区三座中立兵工厂。占一座厂，前线就往前挪一条街；运河上的桥和城墙的缺口是巷战里最贵的几格。': '赤焰首都爐城被四支軍隊各佔一角。老城牆裡有中立機場、雷達塔和醫院，城外是煉鋼區、碼頭、商業區和調車場，每個城區三座中立兵工廠。佔一座廠，前線就往前推一條街；運河上的橋和城牆的缺口是巷戰裡最貴的幾格。',  // MAPS.21.blurb
  '64×64 · 4 个阵营 · 海陆空全开的史诗图': '64×64 · 4 個陣營 · 海陸空全開的史詩地圖',  // MAPS.22.size
  '26×18 · 迷雾 · 林间五寨': '26×18 · 迷霧 · 林間五寨',  // MAPS.23.size
  '翠林腹地的老林子，五个寨子散在林间，用一圈山路连着。赤焰的喷火兵从北边的山口进来，轮式车只能走山路，过溪要找浅滩和木桥。翠林人少，靠森林隐蔽、伏击、拖时间。': '翠林腹地的老林子，五個寨子散在林間，用一圈山路連著。赤焰的噴火兵從北邊的山口進來，輪型車只能走山路，過溪要找淺灘和木橋。翠林人少，靠森林隱蔽、伏擊、拖時間。',  // MAPS.23.blurb
