// 说明文案去口语化（2026-11-13）
AWI18n.add('zh-TW', {
  '黑潮阵营的重装步兵，可占领建筑。对步兵类单位和轻型车辆的伤害高于步兵，受到坦克的伤害明显低于步兵。': '黑潮陣營的重裝步兵，可佔領建築。對步兵類單位和輕型車輛的傷害高於步兵，受到戰車的傷害明顯低於步兵。',
  '黑潮阵营的重型坦克，攻击和防御都高于重型坦克。攻击后可再移动 1 格（不可再次攻击）。': '黑潮陣營的重型戰車，攻擊和防禦都高於重型戰車。攻擊後可再移動 1 格（不可再次攻擊）。',
  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。被敌方占领时，己方败北。': '每回合提供 100 資金。停留的我方陸上單位每回合恢復 2 HP（需支付資金）。被敵方佔領時，我方敗北。',
  '大闸的机房。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。在会涨水的关卡中，每占有一座闸房，下一次涨水推迟 1 天；全部占有时停止涨水。': '大閘的機房。停留的我方步兵類單位每回合恢復 2 HP（需支付資金）。在會漲水的關卡中，每佔有一座閘房，下一次漲水延後 1 天；全部佔有時停止漲水。',
  '车辆的移动力更高，步兵类单位的攻击略低。技能“闪击”：本回合全军的移动力和攻击提高。': '車輛的移動力更高，步兵類單位的攻擊略低。技能「閃擊」：本回合全軍的移動力和攻擊提高。',
  '各型坦克的攻击和防御更高，其他单位的攻击较低。技能“履带洪流”：各型坦克攻击后可以再移动。': '輕型、中型、重型戰車的攻擊和防禦更高，其他單位的攻擊較低。技能「履帶洪流」：輕型、中型、重型戰車攻擊後可以再移動。',
  '远程单位的攻击更高，其中自行火炮和火箭炮提高最多。技能“炮火覆盖”：所有敌方单位损失 HP。': '遠程單位的攻擊更高，其中自走砲和火箭砲提高最多。技能「砲火覆蓋」：所有敵方單位損失 HP。',
  '新生产的单位当回合可以行动，所有单位造价 +10%。技能“加班”：本回合造价降低，每座生产建筑可以生产 2 次。': '新生產的單位當回合可以行動，所有單位造價 +10%。技能「加班」：本回合造價降低，每座生產建築可以生產 2 次。',
  '赤焰喷火兵部队的指挥官，炉前工出身，脸上有疤。嫌远距离打仗像写信吵架，喜欢凑到跟前。': '赤焰噴火兵部隊的指揮官，爐前工出身，臉上有疤。嫌遠距離打仗像寫信吵架，喜歡湊到面前打。',
  '喷火兵和破甲兵的攻击、移动力更高，造价更低。技能“燎原”：喷火兵的攻击波及周围的敌方单位，并把森林变为荒地。': '噴火兵和破甲兵的攻擊、移動力更高，造價更低。技能「燎原」：噴火兵的攻擊波及周圍的敵方單位，並把森林變為荒地。',
  '己方单位被相邻的敌方单位攻击时先手反击。技能“架盾”：反击伤害 ×2，全军防御提高。': '我方單位被相鄰的敵方單位攻擊時先制反擊。技能「架盾」：反擊傷害 ×2，全軍防禦提高。',
  '舰船的攻击、防御和移动力更高，造价更低。技能“怒潮”：全军恢复 HP，舰船对陆上单位的伤害提高。': '艦艇的攻擊、防禦和移動力更高，造價更低。技能「怒潮」：全軍恢復 HP，艦艇對陸上單位的傷害提高。',
  '攻击机、轰炸机、战斗机的攻击更高，造价更低。技能“俯冲”：航空单位攻击时不受反击。': '攻擊機、轟炸機、戰鬥機的攻擊更高，造價更低。技能「俯衝」：航空單位攻擊時不受反擊。',
  '武装直升机的攻击和防御更高，运输直升机的搭载数更多。技能“蜂群”：直升机攻击后可以再移动。': '武裝直升機的攻擊和防禦更高，運輸直升機的搭載數更多。技能「蜂群」：直升機攻擊後可以再移動。',
  '潜艇的攻击更高，只有相邻时才会被发现。技能“狼群”：潜艇攻击大幅提高，攻击时不受反击。': '潛艦的攻擊更高，只有相鄰時才會被發現。技能「狼群」：潛艦攻擊大幅提高，攻擊時不受反擊。',
  '防空车、防空导弹和战斗机对航空单位的伤害更高，造价更低。技能“天网”：敌方航空单位进入射程时自动受到攻击。': '防空車、防空飛彈和戰鬥機對航空單位的傷害更高，造價更低。技能「天網」：敵方航空單位進入射程時自動受到攻擊。',
  '苍蓝舰队医院的医生。送到他手上的人，不管哪一方的，都要活着下手术台。爱管别人吃没吃饭。': '蒼藍艦隊醫院的醫生。送到他手上的人，不管哪一方的，都要活著下手術台。愛管別人吃飯了沒。',
  '己方单位每回合恢复 1 HP，在建筑上修理免费。技能“急救”：全军恢复 HP，并复活最近被击毁的一个单位。': '我方單位每回合恢復 1 HP，在建築上修理免費。技能「急救」：全軍恢復 HP，並復活最近被擊毀的一個單位。',
  '步兵类单位的攻击、占领值和视野更高。技能“全民皆兵”：己方城市出现步兵。': '步兵類單位的攻擊、佔領值和視野更高。技能「全民皆兵」：我方城市出現步兵。',
  '狙击手的射程和攻击更高，移动后可以攻击。技能“一击”：狙击手、投弹手的运气取最大值，并无视目标的地形防御。': '狙擊手的射程和攻擊更高，移動後可以攻擊。技能「一擊」：狙擊手、投彈手的運氣取最大值，並無視目標的地形防禦。',
  '翠林负责山路和暗号的人，没人说得清她是哪个寨子的。擅长让对手先看见一点东西，再发现看错了。': '翠林負責山路和暗號的人，沒人說得清她是哪個寨子的。擅長讓對手先看見一點東西，再發現自己看錯了。',
  '位于森林、废墟、礁石的己方单位攻击和防御更高，只有相邻时才会被发现。技能“灯火管制”：敌方单位的视野降为 1。': '位於森林、廢墟、礁石的我方單位攻擊和防禦更高，只有相鄰時才會被發現。技能「燈火管制」：敵方單位的視野降為 1。',
  '直射单位攻击后，可以用剩余的移动力再移动。技能“风驰”：全军移动力提高，攻击时不受反击。': '直射單位攻擊後，可以用剩餘的移動力再移動。技能「風馳」：全軍移動力提高，攻擊時不受反擊。',
  '己方单位在能进入的地形上，移动消耗都是 1。技能“寒潮”：敌方单位的移动力和视野降低。': '我方單位在能進入的地形上，移動消耗都是 1。技能「寒流」：敵方單位的移動力和視野降低。',
  '己方单位的攻击不随 HP 减少而降低。技能“背水”：HP 未满的单位攻击大幅提高。': '我方單位的攻擊不隨 HP 減少而降低。技能「背水」：HP 未滿的單位攻擊大幅提高。',
  '金沙七邦的司库，主管财务。只认账本，不划算的仗不打。脾气很好，从不发火，因为发火不挣钱。': '金沙七邦的司庫，主管財務。只認帳本，不划算的仗不打。脾氣很好，從不發火，因為發火賺不到錢。',
  '所有单位造价 −10%，全军攻击 −10%。技能“军费”：立即获得一笔资金。': '所有單位造價 −10%，全軍攻擊 −10%。技能「軍費」：立即獲得一筆資金。',
  '金沙的佣兵首领，赌场少东家。谁出价高替谁打，只押赢的那边。': '金沙的傭兵首領，賭場少東。誰出價高就替誰打，只押會贏的那邊。',
  '攻击的运气范围很大，伤害的起伏也大。技能“梭哈”：运气判定三次，取最高值。': '攻擊的運氣範圍很大，傷害的起伏也大。技能「梭哈」：運氣判定三次，取最高值。',
  '占领值更高，每占领一座建筑都获得资金。技能“加征”：立即获得相当于一个回合的收入。': '佔領值更高，每佔領一座建築都獲得資金。技能「加徵」：立即獲得相當於一個回合的收入。',
  '己方城市也可以生产步兵类单位，步兵类单位造价更低。技能“黑市”：可以出售己方单位，返还造价的 90%。': '我方城市也可以生產步兵類單位，步兵類單位造價更低。技能「黑市」：可以出售我方單位，返還造價的 90%。',
  '侦察车、摩托兵的移动力和攻击更高，攻击后可以再移动。技能“穿插”：侦察车、摩托兵、运兵车可以穿过敌方单位。': '偵察車、機車兵的移動力和攻擊更高，攻擊後可以再移動。技能「穿插」：偵察車、機車兵、運兵車可以穿過敵方單位。',
  '位于建筑或 2 星及以上地形的单位防御更高。技能“铁壁”：全军恢复 HP，防御提高。': '位於建築或 2 星及以上地形的單位防禦更高。技能「鐵壁」：全軍恢復 HP，防禦提高。',
  '黑潮阵营的首领，六十六岁，见过三次退潮。六岁那次没了家，三十六岁那次没了妻儿。劝和、划界、分矿他都试过，每次只管三十年。说话慢，从不提高声音，说过的话一定算数。': '黑潮陣營的首領，六十六歲，見過三次退潮。六歲那次沒了家，三十六歲那次沒了妻兒。勸和、劃界、分礦他都試過，每次只管用三十年。說話慢，從不提高音量，說過的話一定算數。',
  '位于荒地、废墟、陨星矿的己方单位防御更高。技能“开闸”：涨水一级，与海洋相邻的沙滩、荒地、礁石、废墟变为海洋。': '位於荒地、廢墟、隕星礦的我方單位防禦更高。技能「開閘」：漲水一級，與海洋相鄰的沙灘、荒地、礁石、廢墟變為海洋。',
  '主管海军': '主管海軍',
  '黑潮阵营的大将，主管海军。五十八岁，老船长，四国通用的潮汐表是他年轻时编的。上一次战争，他的船队被四国轮流征用，沉得一条不剩。从那以后他只信海。像个教书先生，动手之前先讲道理。': '黑潮陣營的大將，主管海軍。五十八歲，老船長，四國通用的潮汐表是他年輕時編的。上一次戰爭，他的船隊被四國輪流徵用，沉得一艘不剩。從那以後他只信海。像個教書先生，動手之前先講道理。',
  '舰船的攻击和移动力更高；迷雾开启时，视野范围内礁石里的敌方单位也可见。技能“大潮”：敌方舰船的移动力大幅降低。': '艦艇的攻擊和移動力更高；迷霧開啟時，視野範圍內礁石裡的敵方單位也可見。技能「大潮」：敵方艦艇的移動力大幅降低。',
  '主管财务': '主管財務',
  '黑潮阵营的大将，主管财务，负责收买对手。四十一岁。她家三代的商行在上一次战争里赔得精光。她算过：打仗是世上最亏的买卖，每三十年亏一次，不如一次清账。客气，从不发火，说话只说一遍。': '黑潮陣營的大將，主管財務，負責收買對手。四十一歲。她家三代的商行在上一次戰爭裡賠得精光。她算過：打仗是世上最虧的買賣，每三十年虧一次，不如一次結清。客氣，從不發火，話只說一遍。',
  '所有单位造价更低，击毁敌方单位可以获得资金。技能“收购”：支付资金，买下与己方单位相邻的敌方车辆，最多 2 个。': '所有單位造價更低，擊毀敵方單位可以獲得資金。技能「收購」：支付資金，買下與我方單位相鄰的敵方車輛，最多 2 個。',
  '主管交通': '主管交通',
  '黑潮阵营的大将，主管交通，黑色装甲列车“黑潮号”的车长。三十五岁，修了半辈子路。他修的每一条路都被拿去运兵，路铺到哪，仗打到哪。他想铺完最后一条，从此世上不用再铺路。话少，力气大，认死理。': '黑潮陣營的大將，主管交通，黑色裝甲列車「黑潮號」的列車長。三十五歲，修了半輩子路。他修的每一條路都被拿去運兵，路鋪到哪，仗打到哪。他想鋪完最後一條，從此世上不用再鋪路。話少，力氣大，死腦筋。',
  '车辆在道路和桥梁上的防御更高；回合开始时位于道路、桥梁的车辆移动力更高。技能“封路”：敌方单位在道路和桥梁上的移动消耗增加。': '車輛在道路和橋梁上的防禦更高；回合開始時位於道路、橋梁的車輛移動力更高。技能「封路」：敵方單位在道路和橋梁上的移動消耗增加。',
  '主管情报': '主管情報',
  '黑潮阵营的大将，主管情报：潜伏，冒充，挑拨。二十四岁。她是在战争烧剩的寨子里被玄渊捡回来的孩子，管他叫爷爷。爱笑，说话像开玩笑，下手不开玩笑。': '黑潮陣營的大將，主管情報：潛伏，冒充，挑撥。二十四歲。她是在戰火燒剩的寨子裡被玄淵撿回來的孩子，叫他爺爺。愛笑，說話像開玩笑，下手不開玩笑。',
  '位于建筑的己方步兵类单位处于隐蔽状态。技能“点灯”：让分属两个敌方阵营的相邻单位互相攻击。': '位於建築的我方步兵類單位處於隱蔽狀態。技能「點燈」：讓分屬兩個敵方陣營的相鄰單位互相攻擊。',
  '本回合：狙击手、投弹手攻击时，运气取最大值，并无视目标的地形防御。全军攻击 +30%。': '本回合：狙擊手、投彈手攻擊時，運氣取最大值，並無視目標的地形防禦。全軍攻擊 +30%。',
  '本回合：己方攻击的运气判定三次，取最高值。全军攻击 +30%。第一次击毁敌方单位时，返还 50% 技能槽。': '本回合：我方攻擊的運氣判定三次，取最高值。全軍攻擊 +30%。第一次擊毀敵方單位時，返還 50% 技能槽。',
  '本回合：单位造价 −30%，每座生产建筑可生产 2 次。生产第二个单位前，要先把第一个单位移出建筑。': '本回合：單位造價 −30%，每座生產建築可生產 2 次。生產第二個單位前，要先將第一個單位移出建築。',
  '己方下回合开始前：敌方航空单位移动后进入己方防空车、防空导弹、战斗机的射程时，自动受到一次攻击（每个己方单位一次）。全军防御 +30%。': '我方下回合開始前：敵方航空單位移動後進入我方防空車、防空飛彈、戰鬥機的射程時，自動受到一次攻擊（每個我方單位一次）。全軍防禦 +30%。',
  '立即获得相当于一个回合的收入。本回合：步兵类单位移动力 +1。': '立即獲得相當於一個回合的收入。本回合：步兵類單位移動力 +1。',
  '打开大闸，涨水一级。与海洋相邻的沙滩、荒地、礁石、废墟变为海洋。位于这些格子的陆上单位被移到最近的空格，其中敌方单位损失 3 HP（不会被击毁）。己方下回合开始前：全军防御 +20%。每局最多涨水 2 次。不能涨水时，改为所有敌方单位各损失 1 HP（不会被击毁）。': '打開大閘，漲水一級。與海洋相鄰的沙灘、荒地、礁石、廢墟變為海洋。位於這些格子的陸上單位被移到最近的空格，其中敵方單位損失 3 HP（不會被擊毀）。我方下回合開始前：全軍防禦 +20%。每場對戰最多漲水 2 次。不能漲水時，改為所有敵方單位各損失 1 HP（不會被擊毀）。',
  '买下与己方单位相邻的敌方车辆，最多 2 个，从价格高的开始买。买下的单位立即归己方所有，当回合不能行动。价格 = 造价 × 剩余 HP ÷ 10 × 50%。资金不够支付的单位不会买下。以下单位不能买：带标记的单位、搭载着单位的运输单位、位于司令部的单位、敌方阵营的最后一个单位。一个单位都没有买下时，改为获得回合收入的 50%。': '買下與我方單位相鄰的敵方車輛，最多 2 個，從價格高的開始買。買下的單位立即歸我方所有，當回合不能行動。價格 = 造價 × 剩餘 HP ÷ 10 × 50%。資金不夠支付的單位不會買下。以下單位不能買：帶標記的單位、搭載著單位的運輸單位、位於司令部的單位、敵方陣營的最後一個單位。一個單位都沒有買下時，改為獲得回合收入的 50%。',
  '相邻且分属不同敌方阵营的两个单位互相攻击一次，最多 2 对，每个单位只算进一对。这次攻击不会击毁单位，也不积累技能槽。没有符合条件的单位时，改为以下效果。本回合：己方攻击 +20%，攻击时不受反击。己方下回合开始前：敌方视野 −2。': '相鄰且分屬不同敵方陣營的兩個單位互相攻擊一次，最多 2 對，每個單位只算進一對。這次攻擊不會擊毀單位，也不累積技能槽。沒有符合條件的單位時，改為以下效果。本回合：我方攻擊 +20%，攻擊時不受反擊。我方下回合開始前：敵方視野 −2。',
  '远程：移动后不可攻击，只有不移动时才可以攻击。': '遠程：移動後不可攻擊，只有不移動時才可以攻擊。',
  '一个阵营的司令部被占领，或者全部单位被击毁时，这个阵营败北。只剩一支队伍时，这支队伍获胜。': '一個陣營的司令部被佔領，或者全部單位被擊毀時，這個陣營敗北。只剩一支隊伍時，這支隊伍獲勝。',
  '受到相邻敌方单位攻击的单位如果没有被击毁，会反击，伤害按受到攻击后的 HP 计算。': '受到相鄰敵方單位攻擊的單位如果沒有被擊毀，會反擊，傷害按受到攻擊後的 HP 計算。',
  '远程单位移动后不可攻击，只有不移动时才可以攻击。{list}例外，移动后仍可攻击。': '遠程單位移動後不可攻擊，只有不移動時才可以攻擊。{list}例外，移動後仍可攻擊。',
  '远程单位移动后不可攻击，只有不移动时才可以攻击。': '遠程單位移動後不可攻擊，只有不移動時才可以攻擊。',
  '没有添加内容': '沒有新增內容',
  '上一局使用了这些扩展，现在没有启用，所以不能继续：{list}。存档仍然保留，重新启用这些扩展后可以继续。': '上一場對戰使用了這些模組，現在沒有啟用，所以不能繼續：{list}。存檔仍然保留，重新啟用這些模組後可以繼續。',
  'id「{a}」和文件夹名「{b}」不一致': 'id「{a}」和資料夾名稱「{b}」不一致',
  '同一个 id 重复登记': '同一個 id 重複註冊',
  '{a} 必须是数组': '{a} 必須是陣列',
  '{a} 必须是对象': '{a} 必須是物件',
  '地图「{a}」的 rows / half 必须是等宽的字符串数组': '地圖「{a}」的 rows / half 必須是等寬的字串陣列',
  '指挥官「{a}」的 faction 必须是 1–5': '指揮官「{a}」的 faction 必須是 1–5',
  '指挥官「{a}」的 mods 必须是数组': '指揮官「{a}」的 mods 必須是陣列',
  '指挥官「{a}」的 mods 里有无法识别的字段 {b}': '指揮官「{a}」的 mods 裡有無法辨識的欄位 {b}',
  '指挥官「{a}」的 mods 里有无法识别的兵种类别 {b}': '指揮官「{a}」的 mods 裡有無法辨識的兵種類別 {b}',
  '指挥官「{a}」的 {b} 必须是对象': '指揮官「{a}」的 {b} 必須是物件',
  '指挥官「{a}」的 fx.{b} 里有无法识别的兵种类别 {c}': '指揮官「{a}」的 fx.{b} 裡有無法辨識的兵種類別 {c}',
  'balance 里有无法识别的字段 {a}': 'balance 裡有無法辨識的欄位 {a}',
  'mod.js 没有调用 AWMods.register（脚本出错，或者 id 不一致）': 'mod.js 沒有呼叫 AWMods.register（腳本出錯，或者 id 不一致）',
  '扩展 id 里有不能使用的字符': '模組 id 裡有不能使用的字元',
  '指挥官「{a}」的 rules 里有无法识别的效果 {b}': '指揮官「{a}」的 rules 裡有無法辨識的效果 {b}',
  '指挥官「{a}」的 fx 里有无法识别的效果 {b}': '指揮官「{a}」的 fx 裡有無法辨識的效果 {b}',
  '获得 S 评价的指挥官': '獲得 S 評價的指揮官',
  '只有一名玩家对战电脑的对局才评分。': '只有一名玩家對抗電腦的對戰才評分。',
  '开局资金、建筑收入、人数补偿使用这张地图的默认设置时才评分。': '初始資金、建築收入、人數補償使用這張地圖的預設設定時才評分。',
  '队伍使用这张地图的默认分法时才评分。': '隊伍使用這張地圖的預設分法時才評分。',
  '这位指挥官首次获得 S 评价': '這位指揮官首次獲得 S 評價',
  '在困难难度获得 S 评价': '在困難難度獲得 S 評價',
  '距离 S 评价还差 {n} 分': '距離 S 評價還差 {n} 分',
  '完成过对局的地图': '完成過對戰的地圖',
  '黑潮阵营的大将，主管海军。四国通用的潮汐表是他年轻时编的。': '黑潮陣營的大將，主管海軍。四國通用的潮汐表是他年輕時編的。',
  '黑潮阵营的大将，主管情报。她是在烧剩的寨子里被玄渊捡回来的孩子，管他叫爷爷。': '黑潮陣營的大將，主管情報。她是在燒剩的寨子裡被玄淵撿回來的孩子，叫他爺爺。',
  '黑潮阵营的大将，主管财务，负责收买对手。她家三代的商行在上一次战争里赔光了。': '黑潮陣營的大將，主管財務，負責收買對手。她家三代的商行在上一次戰爭裡賠光了。',
  '位于森林、废墟、礁石的己方单位攻击 +20%、防御 +20%，迷雾关闭时也处于隐蔽状态。位于平原、道路、桥梁、沙滩的己方单位防御 −5%。迷雾开启时全军视野 +2。己方单位移动中遇到隐蔽的敌方单位时停止移动，但行动不结束。': '位於森林、廢墟、礁石的我方單位攻擊 +20%、防禦 +20%，迷霧關閉時也處於隱蔽狀態。位於平原、道路、橋梁、沙灘的我方單位防禦 −5%。迷霧開啟時全軍視野 +2。我方單位移動中遇到隱蔽的敵方單位時停止移動，但行動不結束。',
  '己方攻击的运气范围变为 0 至 +40（原来 0–9）。运气超过 9 的部分按比例计入伤害：计入量 = 超出部分 × 基础伤害 ÷ 100（基础伤害超过 100 时按 100 计算）。': '我方攻擊的運氣範圍變為 0 至 +40（原來 0–9）。運氣超過 9 的部分按比例計入傷害：計入量 = 超出部分 × 基礎傷害 ÷ 100（基礎傷害超過 100 時按 100 計算）。',
  '占领值 ×1.5。每占领一座建筑，获得 150 资金；占领的是敌方建筑时，再获得 150 资金。全军攻击 −10%。': '佔領值 ×1.5。每佔領一座建築，獲得 150 資金；佔領的是敵方建築時，再獲得 150 資金。全軍攻擊 −10%。',
  '位于建筑的己方步兵类单位处于隐蔽状态，迷雾关闭时也有效。步兵类单位攻击 +15%、占领值 ×1.5。迷雾开启时全军视野 +1。': '位於建築的我方步兵類單位處於隱蔽狀態，迷霧關閉時也有效。步兵類單位攻擊 +15%、佔領值 ×1.5。迷霧開啟時全軍視野 +1。',
  '各型坦克防御 +15%。': '輕型、中型、重型戰車防禦 +15%。',
  '远程单位攻击时，目标的地形防御 −1 星。': '遠程單位攻擊時，目標的地形防禦 −1 星。',
  '远程单位攻击后，目标相邻四格内的敌方单位各受到本次伤害的 20%（不会被击毁；每个单位每回合因溅射最多损失 5 HP）。': '遠程單位攻擊後，目標相鄰四格內的敵方單位各受到本次傷害的 20%（不會被擊毀；每個單位每回合因濺射最多損失 5 HP）。',
  '每经过 4 个己方回合，没有单位的己方城市各免费出现一个步兵，每次最多 4 个，当回合可行动。': '每經過 4 個我方回合，沒有單位的我方城市各免費出現一個步兵，每次最多 4 個，當回合可行動。',
  '每座兵工厂每回合额外提供 1 研究点，最多 4 研究点；研究经费选“停”档时仍然有效。': '每座兵工廠每回合額外提供 1 研究點，最多 4 研究點；研究經費選「停」級時仍然有效。',
  '每回合额外获得 5 研究点（研究经费选“停”档时没有）。各档研究经费 +20%。': '每回合額外獲得 5 研究點（研究經費選「停」級時沒有）。各級研究經費 +20%。',
  '每个敌方回合，第一个移动后进入己方防空导弹射程的敌方航空单位自动受到一次攻击。': '每個敵方回合，第一個移動後進入我方防空飛彈射程的敵方航空單位自動受到一次攻擊。',
  '位于山地、沼泽的己方单位也处于隐蔽状态，规则与森林、废墟、礁石相同。': '位於山地、沼澤的我方單位也處於隱蔽狀態，規則與森林、廢墟、礁石相同。',
  '每回合第一次主动攻击时，运气判定两次，取较高值。': '每回合第一次主動攻擊時，運氣判定兩次，取較高值。',
});
